<section class="heading">
    <div><p class="eyebrow">Nota fiscal</p><h1>NF-e <?= h($invoice['number'] ?: 'sem número') ?></h1><p><?= h($invoice['supplier'] ?: 'Fornecedor não informado') ?> · Série <?= h($invoice['series'] ?: '—') ?> · <?= h(date_br($invoice['issuedAt'])) ?></p></div>
    <div class="actions"><?php if ($invoice['status']==='draft' && can('edit_invoices')): ?><a class="button primary" href="<?= h(page_url('invoice-edit',['id'=>(int)$invoice['id']])) ?>">Revisar rascunho</a><?php endif; ?><?php if (!empty($invoice['xml']) && can('export_data')): ?><a class="button" href="<?= h(page_url('download-xml',['id'=>(int)$invoice['id']])) ?>">Baixar XML original</a><?php endif; ?><a class="button" href="<?= h(page_url('invoices')) ?>">Voltar</a></div>
</section>
<section class="panel"><div class="panel-head"><div><h2>Dados fiscais</h2><p>Campos originais preservados; situação baseada no XML recebido.</p></div><span class="badge <?= $invoice['status']==='registered'?'green':'amber' ?>"><?= h(status_label($invoice['status'])) ?></span></div><div class="panel-body form-grid">
    <div><span class="hint">Fornecedor</span><p><strong><?= h($invoice['supplier'] ?: '—') ?></strong></p></div><div><span class="hint">CNPJ fornecedor</span><p><?= h($invoice['supplierCnpj'] ?: '—') ?></p></div><div><span class="hint">Destinatário</span><p><?= h($invoice['recipient'] ?: '—') ?></p></div><div><span class="hint">Emissão / total</span><p><?= h(date_br($invoice['issuedAt'])) ?> · <strong><?= h(money_br($invoice['total'])) ?></strong></p></div>
    <div class="span-2"><span class="hint">Chave de acesso</span><p><code><?= h($invoice['accessKey'] ?: 'Não informada') ?></code></p></div><div><span class="hint">Status conforme XML</span><p><?= h($invoice['xmlStatus'] ?: 'Sem protocolo no XML') ?></p></div><div><span class="hint">Origem</span><p><?= $invoice['source']==='xml'?'Importada de XML':'Cadastro manual' ?></p></div>
    <?php if ($invoice['notes']!==''): ?><div class="span-2"><span class="hint">Observações</span><p><?= nl2br(h($invoice['notes'])) ?></p></div><?php endif; ?>
</div></section>
<section class="panel"><div class="panel-head"><div><h2>Itens da NF-e</h2><p><?= number_format(count($invoice['items']),0,',','.') ?> item(ns) · revisão patrimonial é controlada pelas permissões da conta.</p></div></div>
    <?php if (!$invoice['items']): ?><div class="empty">Nenhum item cadastrado.</div><?php else: ?><div class="table-wrap"><table class="table"><thead><tr><th>Item</th><th>Classificação</th><th>Quantidade</th><th>Conta Patrimonial/local</th><th>Patrimônio</th><th>Total</th></tr></thead><tbody>
        <?php foreach ($invoice['items'] as $item): ?><tr><td><strong><?= h($item['name'] ?: $item['originalDescription']) ?></strong><div class="hint">XML: <?= h($item['originalDescription']) ?></div></td><td><?= h(match($item['classification']){'fixed'=>'Ativo Fixo','small'=>'Pequeno valor','skip'=>'Não incorporar',default=>$item['classification']}) ?></td><td><?= h($item['quantity']) ?> <?= h($item['unit']) ?></td><td><?= h($item['category'] ?: '—') ?><div class="hint"><?= h($item['location'] ?: '') ?></div></td><td><?= h($item['patrimony'] ?: '—') ?></td><td class="money"><?= h(money_br($item['total'])) ?></td></tr><?php endforeach; ?>
    </tbody></table></div><?php endif; ?><div class="panel-body"><p class="footer-note">A NF-e XML só pode ser incorporada se trouxer protocolo com código de autorização 100 ou 150. O sistema não consulta a SEFAZ. Itens “Não incorporar” permanecem na nota, sem criar ativos.</p></div>
</section>
